#!/usr/bin/env node
/* Compare browser data with files generated by the actual iOS MatchExporter
   and MatchHTMLExporter. NativeDemoParitySeedTests writes the references. */
"use strict";
const assert=require("node:assert/strict"),fs=require("node:fs"),path=require("node:path"),vm=require("node:vm"),crypto=require("node:crypto");
const directory=process.argv[2]||"/tmp/deucemate-native-export-references";
const assets=path.resolve(__dirname,"../docs/website/assets"),context=vm.createContext({console,document:{querySelectorAll:()=>[]},window:{}});
function load(name){vm.runInContext(fs.readFileSync(path.join(assets,name),"utf8"),context);}
load("watch-demo.js");load("watch-demo-tracking.js");
context.window.DeuceMateShell={history:[],settings:{track:false},screens:{},api:{}};
load("watch-demo-history.js");context.window.DeuceMateShell.seedHistory();
for(const file of ["phone-demo-native-export.js","phone-demo-coaching.js","phone-demo-export.js","phone-demo-reports.js"])load(file);
function uuid(id){const x=crypto.createHash("sha256").update(id).digest("hex").slice(0,32);return [x.slice(0,8),x.slice(8,12),x.slice(12,16),x.slice(16,20),x.slice(20)].join("-").toUpperCase();}
const reports=context.window.DeuceMatePhoneReports;
const fixture=JSON.parse(fs.readFileSync(process.argv[3]||"/tmp/deucemate-native-parity.json","utf8"));
const normalize=value=>JSON.parse(JSON.stringify(value,(_key,item)=>item===null?undefined:item));
const pointKeys=["index","setIndex","server","winner","outcome","chipText","chipColorHex","outcomeText","isSecondServe","isBreakPoint","isTiebreak","cumulativeMe","cumulativeOpp","heartRateBPM","stepsCumulative","outcomeLabel","endingShotLabel","endingShotColorHex","endingShotSymbol","pointScoreLabel","gameScoreLabel","matchScoreLabel","gameScoreAfterPointLabel","matchScoreAfterPointLabel"];
let rows=0;
for(const original of context.window.DeuceMateShell.history)for(const focal of ["me","opponent"]){
  const saved=fixture.records.find(r=>r.id===uuid(original.id));
  const record={...original,stats:saved.stats.map(p=>({...p,timestamp:(p.timestamp+978307200)*1000}))};
  const name=path.join(directory,uuid(record.id)+"."+focal);
  const nativePrompt=fs.readFileSync(name+".ai.txt","utf8"),browserPrompt=reports.reportText(record,record.stats,focal,"ai");
  const raw=text=>text.split("\n").filter(line=>/^\| \d+ \|/.test(line));
  assert.deepEqual(raw(browserPrompt),raw(nativePrompt),`${record.id}/${focal}: every raw-point cell matches the iOS prompt`);rows+=raw(nativePrompt).length;
  const nativeHTML=fs.readFileSync(name+".html","utf8"),data=JSON.parse(nativeHTML.match(/const DATA = (\{[\s\S]*?\});\n<\/script>/)[1].replaceAll("<\\!--", "<!--")),browser=reports.exportModel(record,record.stats,focal);
  for(let i=0;i<data.points.length;i++)for(const key of pointKeys)assert.equal(browser.points[i][key]??null,data.points[i][key]??null,`${record.id}/${focal} point ${i+1}: ${key}`);
  assert.deepEqual(normalize(browser.filters.map(f=>f.comparison)),normalize(data.filters.map(f=>f.comparison)),`${record.id}/${focal}: native comparison values and sections`);
  assert.equal(browser.perspectives.me.pointsWon,data.perspectives.me.pointsWon);
}
process.stdout.write(`Native export parity passed: 18 reports and ${rows} raw-point rows match iOS.\n`);
